<script setup lang="ts">
import {ref,computed,watch,onMounted,onBeforeUnmount} from 'vue'
import MetricChart from './MetricChart.vue'
import {useRoute} from 'vue-router'
import {api,errorText,type Store,type Analysis} from './api'
const route=useRoute();const stores=ref<Store[]>([]);const store=ref<number>();const dates=ref<[string,string]>(['2026-01-01','2026-03-31']);const sku=ref('');const windowDays=ref(30);const safety=ref(7);const loading=ref(false);const error=ref('');const data=ref<Analysis>();let controller:AbortController|undefined
const page=computed(()=>route.path.slice(1));const titles:Record<string,string>={overview:'经营总览',profit:'利润分析',advertising:'广告分析',inventory:'库存风险'}
const endpoints:Record<string,string>={overview:'/dashboard/overview',profit:'/analytics/profit',advertising:'/analytics/advertising',inventory:'/analytics/inventory-risk'}
const reasons:Record<string,string>={missing_cost:'缺少有效历史成本',no_sales:'无销售记录',nonpositive_net_revenue:'净收入非正，利润率不可计算',currency_mismatch:'币种不一致',zero_spend:'广告花费为零',zero_attributed_sales:'归因销售额为零',zero_clicks:'点击量为零',no_ad_records:'无广告记录',insufficient_history:'销量历史不足',zero_sales:'观察期销量为零',missing_snapshot:'缺少库存快照',stale_snapshot:'库存快照已过期',demand_censored_by_stockout:'断货影响需求估计',no_products:'暂无商品'}
const risk:Record<string,string>={unknown:'数据不足',stockout:'已断货',at_risk:'断货风险',healthy:'正常',slow_moving_stock:'滞销积压',zero_sales_stock:'有库存但零销量'}
function reason(values:string[]){return values.map(v=>reasons[v]||v).join('；')||'—'}
function format(v:unknown,percent=false){if(v===null||v===undefined)return '—';const n=Number(v);return Number.isFinite(n)?(percent?(n*100).toFixed(2)+'%':n.toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})):'—'}
async function load(){controller?.abort();data.value=undefined;error.value='';if(!store.value||!dates.value?.[0]||!dates.value?.[1]){loading.value=false;return};const own=new AbortController();controller=own;loading.value=true;try{const r=await api.get<Analysis>(endpoints[page.value]!,{signal:own.signal,params:{store_id:store.value,start_date:dates.value[0],end_date:dates.value[1],sku:sku.value.trim()||undefined,window:windowDays.value,safety_days:safety.value}});data.value=r.data}catch(e){if(!own.signal.aborted)error.value=errorText(e)}finally{if(controller===own)loading.value=false}}
async function loadStores(){try{stores.value=(await api.get<Store[]>('/stores')).data;if(!stores.value.length){error.value='暂无店铺，请先确认后端连接了 demo 数据库';return}store.value=stores.value[0]!.id}catch(e){error.value=errorText(e)}}
watch([page,store,dates,windowDays,safety],load,{deep:true});onMounted(loadStores);onBeforeUnmount(()=>controller?.abort())
const status=ref('all');const order=ref('contribution_profit');
const groups=computed(()=>page.value==='overview'?['profit','advertising','inventory']:[page.value])
const columns:Record<string,{key:string;label:string;percent?:boolean}[]>={profit:[{key:'quantity',label:'销量 / 件'},{key:'net_revenue',label:'净销售收入'},{key:'purchase_cost',label:'商品成本'},{key:'logistics_cost',label:'物流成本'},{key:'platform_fees',label:'平台费用'},{key:'ad_spend',label:'广告费用'},{key:'contribution_profit',label:'贡献利润'},{key:'profit_margin',label:'利润率',percent:true}],advertising:[{key:'spend',label:'广告花费'},{key:'attributed_sales',label:'归因销售额'},{key:'clicks',label:'点击量'},{key:'ad_orders',label:'广告订单'},{key:'acos',label:'ACOS',percent:true},{key:'roas',label:'ROAS'},{key:'cpc',label:'CPC'},{key:'conversion_rate',label:'转化率',percent:true}],inventory:[{key:'available',label:'可售 / 件'},{key:'inbound',label:'在途 / 件'},{key:'average_daily_sales',label:'日均销量'},{key:'coverage_days',label:'覆盖 / 天'},{key:'lead_time_days',label:'提前期 / 天'},{key:'suggested_replenishment',label:'建议补货 / 件'}]}
function rows(group:string):any[]{const values:any[]=data.value?.[group as 'profit'|'advertising'|'inventory']||[];if(group==='inventory')return values.filter(r=>status.value==='all'||r.risk===status.value);if(group==='profit')return [...values].sort((a,b)=>a[order.value]===null?1:b[order.value]===null?-1:Number(b[order.value])-Number(a[order.value]));return values}
function selectSku(value:string){sku.value=value;load()}
const charts=computed(()=>{
 const profit=rows('profit');const ads=[...rows('advertising')].sort((a,b)=>a.acos===null?1:b.acos===null?-1:Number(b.acos)-Number(a.acos));const inventory=rows('inventory');
 const number=(v:unknown,scale=1)=>v===null?null:Number(v)*scale;
 const result=[];
 if(page.value==='overview'||page.value==='profit'){result.push({title:'SKU 贡献利润排行',labels:profit.map(r=>r.sku),series:[{name:'贡献利润',values:profit.map(r=>number(r.contribution_profit))}],unit:data.value?.currency||'USD'});if(page.value==='profit')result.push({title:'贡献利润率对比',labels:profit.map(r=>r.sku),series:[{name:'贡献利润率',values:profit.map(r=>number(r.profit_margin,100))}],unit:'%'});}
 if(page.value==='overview'||page.value==='advertising'){result.push({title:'SKU ACOS 排行',labels:ads.map(r=>r.sku),series:[{name:'ACOS',values:ads.map(r=>number(r.acos,100))}],unit:'%'});if(page.value==='advertising')result.push({title:'广告花费与归因销售额',labels:ads.map(r=>r.sku),series:[{name:'广告花费',values:ads.map(r=>number(r.spend))},{name:'归因销售额',values:ads.map(r=>number(r.attributed_sales))}],unit:data.value?.currency||'USD'});}
 if(page.value==='inventory')result.push({title:'库存覆盖天数',labels:inventory.map(r=>r.sku),series:[{name:'覆盖天数',values:inventory.map(r=>number(r.coverage_days))}],unit:'天',cap:90});
 return result;
})
</script>
<template><section><div class="eyebrow">BUSINESS WORKSPACE</div><h1>{{titles[page]}}</h1><p>从真实经营数据出发，理解收益、投放效率与库存健康。</p><div class="filters"><el-select v-model="store" placeholder="选择店铺" style="width:220px" aria-label="店铺"><el-option v-for="s in stores" :key="s.id" :value="s.id" :label="s.name"/></el-select><el-date-picker v-model="dates" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期" style="width:270px"/><el-input v-model="sku" placeholder="SKU（留空显示全部）" clearable style="width:210px" @change="load"/><template v-if="page==='inventory'||page==='overview'"><label>观察天数 <el-input-number v-model="windowDays" :min="1" :max="365" size="small"/></label><label>安全天数 <el-input-number v-model="safety" :min="0" :max="365" size="small"/></label></template><el-button type="primary" :loading="loading" @click="stores.length?load():loadStores()">刷新数据</el-button></div><el-alert v-if="error" class="error" :title="error" type="error" show-icon :closable="false"/><div v-if="data?.summary" class="kpi-grid"><article v-for="k in [{label:'净销售收入',value:format(data.summary.net_revenue),unit:data.currency},{label:'贡献利润',value:format(data.summary.contribution_profit),unit:data.currency},{label:'广告 ACOS',value:format(data.summary.acos,true),unit:'总花费 / 总归因销售额'},{label:'断货 / 低库存 SKU',value:String(data.summary.inventory_risk_skus),unit:'另有 '+data.summary.inventory_unknown_skus+' 个状态未知'}]" :key="k.label"><span>{{k.label}}</span><strong>{{k.value}}</strong><small>{{k.unit}}</small></article><p>{{reason(data.summary.reasons)}} · 收入/广告 {{dates?.[0]}}～{{dates?.[1]}}；库存截止 {{dates?.[1]}}</p></div><div v-if="data" class="summary"><div><span>统计店铺</span><strong>{{stores.find(s=>s.id===data?.store_id)?.name}}</strong></div><div><span>结算币种</span><strong>{{data.currency}}</strong></div><div><span>返回的 SKU 明细</span><strong>{{Math.max(data.profit.length,data.advertising.length,data.inventory.length)}}</strong></div></div><div class="note">金额单位：{{data?.currency||'店铺币种'}} · “—”表示不可计算或缺失，详情见数据说明。广告归因额不等于店铺销售额；库存不含未到货在途。总览 KPI 由后端确定性服务汇总，不对 SKU 比例取平均。</div><div v-if="data && !error" class="chart-grid"><MetricChart v-for="chart in charts" :key="chart.title" v-bind="chart" @select="selectSku"/></div><div v-if="data && page==='overview'" class="panel"><h2>重点异常 SKU</h2><div class="alerts"><button v-for="r in data.profit.filter(r=>r.contribution_profit!==null && Number(r.contribution_profit)<0)" :key="r.sku" @click="selectSku(r.sku)">⚠ {{r.sku}} · 负贡献利润 {{format(r.contribution_profit)}}</button><button v-for="r in data.inventory.filter(r=>r.risk!=='healthy')" :key="'i'+r.sku" @click="selectSku(r.sku)">⚠ {{r.sku}} · {{risk[r.risk]}}</button></div></div><div v-if="page==='inventory'" class="filters"><label>库存状态</label><el-select v-model="status" style="width:180px"><el-option label="全部状态" value="all"/><el-option v-for="(label,key) in risk" :key="key" :value="key" :label="label"/></el-select></div><div v-if="page==='profit'" class="filters"><label>按指标降序</label><el-select v-model="order" style="width:180px"><el-option label="贡献利润" value="contribution_profit"/><el-option label="净销售收入" value="net_revenue"/><el-option label="贡献利润率" value="profit_margin"/></el-select></div><div v-loading="loading" style="min-height:180px"><div v-for="group in groups" :key="group" class="panel"><h2>{{titles[group]}}</h2><p v-if="group==='inventory'">截止 {{dates?.[1]}}，向前观察 {{windowDays}} 天；库存为历史日末快照。</p><p v-else>{{dates?.[0]}} 至 {{dates?.[1]}} · {{reason(data?.reasons||[])}}</p><el-table :data="rows(group)" stripe empty-text="暂无数据，请选择筛选条件后查询" style="width:100%"><el-table-column prop="sku" label="SKU" fixed min-width="140"/><el-table-column v-for="col in columns[group]" :key="col.key" :label="col.label" min-width="125"><template #default="{row}"><span :class="{'negative':row[col.key]!==null && Number(row[col.key])<0}">{{format(row[col.key],col.percent)}}<span v-if="col.key==='acos' && row.acos!==null && Number(row.acos)>1" class="risk-label"> ⚠ 高 ACOS</span></span></template></el-table-column><el-table-column v-if="group==='inventory'" label="库存状态" min-width="130"><template #default="{row}"><el-tag :type="['stockout','at_risk'].includes(row.risk)?'danger':'info'">{{risk[row.risk]||row.risk}}</el-tag></template></el-table-column><el-table-column v-if="group==='profit'" label="成本变化" width="110"><template #default="{row}">{{row.cost_increased?'成本上涨':'—'}}</template></el-table-column><el-table-column label="数据说明" min-width="220"><template #default="{row}">{{reason(row.reasons)}}</template></el-table-column></el-table></div></div></section></template>
